import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
K=['RSPP-A','RSPP-AGG']
EA(K,'ZR70','Il preposto: individuazione obbligatoria ed emolumento',[SC("La lettera di individuazione","Un’impresa decide di individuare formalmente i capisquadra come preposti. Uno di loro teme di assumersi responsabilità senza benefici.",[
 ("Che cosa deve contenere la lettera?",[["Compiti di vigilanza, area e lavoratori di riferimento, obbligo di formazione e riferimenti per segnalare",True,"Corretto."],["Solo il nome",False,"Non basta."],["Una rinuncia alle responsabilità",False,"Non ha valore."]]),
 ("Il caposquadra ha diritto a un compenso?",[["I contratti collettivi possono stabilire un emolumento; in ogni caso non può subire pregiudizi per lo svolgimento dell’attività",True,"Corretto."],["Sempre un compenso fissato per legge",False,"Lo stabilisce la contrattazione."],["Mai",False,"La contrattazione può prevederlo."]]),
 ("Se rifiutasse l’individuazione, la sua posizione cambierebbe?",[["No, se di fatto continua a sovrintendere: per il principio di effettività resterebbe preposto",True,"Corretto."],["Sì, non avrebbe alcuna responsabilità",False,"Conta l’esercizio effettivo."],["Sì, diventerebbe dirigente",False,"Non è così."]])],
 "L’individuazione del preposto è obbligatoria e va fatta con compiti chiari; il compenso è materia contrattuale e conta comunque l’esercizio effettivo della funzione.","Un caposquadra teme la nomina a preposto. Rispondi ai suoi dubbi.","Art. 18, c. 1, lett. b-bis), e art. 19 D.lgs. 81/2008")])
EA(K,'ZR71','Giurisprudenza: posizioni di garanzia e RSPP',[CL("Principio corretto o errato?","Seleziona un’affermazione, poi la colonna.",["Coerente con la giurisprudenza consolidata","Non coerente"],[
 ["Rileva l’esercizio concreto dei poteri, non la qualifica formale",0,"Principio di effettività."],["L’RSPP non può mai rispondere di un infortunio",1,"Può rispondere in concorso."],
 ["La delega senza autonomia di spesa non trasferisce la posizione di garanzia",0,"Corretto."],["Qualsiasi imprudenza del lavoratore esclude la responsabilità del datore di lavoro",1,"Solo il comportamento abnorme."],
 ["Il committente risponde se sceglie un appaltatore senza verificarne l’idoneità",0,"Culpa in eligendo."],["Il preposto che tollera prassi scorrette non ha colpa se non ha dato ordini",1,"Le prassi tollerate provano la colpa."]],
 "Sei affermazioni sulle posizioni di garanzia. Distingui quelle coerenti con la giurisprudenza consolidata.","Artt. 16, 18, 19, 26 e 299 D.lgs. 81/2008")])
EA(K,'ZR72','Agenti biologici: gruppi e livelli di contenimento',[LB("Laboratorio · Il rischio biologico in un laboratorio di analisi","Imposti la valutazione del rischio biologico in un laboratorio di analisi microbiologiche alimentari.",[
  ["Attività","ricerca di Salmonella, Listeria monocytogenes ed Escherichia coli nei campioni di alimenti; colture e arricchimenti"],["Personale","5 tecnici"],["Strutture","una cappa di sicurezza microbiologica di classe II; autoclave"]],[
  ("A quale gruppo appartengono gli agenti e che cosa comporta?",7,"Salmonella, Listeria monocytogenes ed Escherichia coli sono in genere agenti del gruppo 2, con l’eccezione di alcuni sierotipi, come Salmonella Typhi, del gruppo 3. L’uso deliberato richiede misure di contenimento almeno di livello 2 e la comunicazione all’organo di vigilanza almeno 30 giorni prima dell’inizio.",["Ho classificato gli agenti","Ho indicato il livello 2","Ho indicato la comunicazione preventiva"]),
  ("Quali misure di contenimento e organizzative prevedi?",8,"Manipolazione delle colture sotto cappa di classe II; accesso limitato e segnaletica di rischio biologico; superfici lavabili e disinfettabili; inattivazione dei rifiuti in autoclave; procedure per spandimenti; divieto di mangiare e bere; indumenti dedicati.",["Ho previsto cappa e accesso limitato","Ho previsto gestione dei rifiuti e spandimenti","Ho previsto regole igieniche"],None,120),
  ("Quale sorveglianza sanitaria e quali registrazioni?",6,"Sorveglianza sanitaria con il medico competente; informazione su eventuali vaccinazioni disponibili; registro degli esposti per gli agenti dei gruppi 3 e 4, se manipolati; registrazione degli incidenti con esposizione.",["Ho previsto la sorveglianza","Ho indicato quando serve il registro"]),
  ("Come gestisci un incidente con rottura di una piastra fuori cappa?",6,"Allontanamento dall’area, attesa per la sedimentazione degli aerosol, decontaminazione con disinfettante adeguato e DPI, smaltimento come rifiuto a rischio infettivo, registrazione e valutazione da parte del medico competente.",["Ho previsto allontanamento e decontaminazione","Ho previsto registrazione e medico competente"])],
 "Nel laboratorio imposti la valutazione del rischio biologico in un laboratorio di analisi alimentari: classificazione degli agenti, contenimento, sorveglianza e gestione di un incidente. Confronta ogni risposta con la soluzione di riferimento.","Titolo X e Allegati XLVI-XLVII D.lgs. 81/2008")])
EA(K,'ZR73','Legionella, vaccinazioni e ferite da taglienti',[LB("Laboratorio · Il piano di controllo della Legionella","Imposti il piano di controllo della Legionella per uno stabilimento con spogliatoi, docce e una torre evaporativa.",[
  ["Impianti","acqua calda sanitaria con bollitore centralizzato; 40 docce negli spogliatoi; torre evaporativa per il raffreddamento di processo"],["Situazione","docce poco usate nel periodo estivo; nessun piano"],["Riferimento","Linee guida nazionali per la prevenzione e il controllo della legionellosi del 2015"]],[
  ("Quali sono i punti critici?",6,"Ristagni nelle docce poco usate e nei rami morti; temperature dell’acqua calda nell’intervallo favorevole alla crescita; aerosol della torre evaporativa che può diffondersi all’esterno.",["Ho individuato ristagni e temperature","Ho considerato la torre evaporativa"]),
  ("Quali misure di gestione prevedi?",8,"Valutazione del rischio per ogni impianto; mantenimento dell’acqua calda a temperature che limitano la crescita, con produzione e ricircolo adeguati, e dell’acqua fredda bassa; scorrimento periodico dei punti poco usati; pulizia e disinfezione dei soffioni; manutenzione e trattamento della torre secondo le linee guida; registro degli interventi.",["Ho previsto temperature e scorrimento","Ho previsto manutenzione della torre","Ho previsto il registro"],None,120),
  ("Come organizzi i campionamenti e le risposte agli esiti?",7,"Piano di campionamento con punti rappresentativi e frequenza definita nella valutazione; laboratorio qualificato; azioni graduate in funzione delle concentrazioni secondo le soglie delle linee guida, dalla verifica fino alla disinfezione e all’interdizione dell’uso.",["Ho previsto punti e frequenze","Ho previsto azioni graduate"]),
  ("Chi è responsabile e come si documenta?",5,"Il datore di lavoro, con un responsabile designato per la gestione degli impianti; documento di valutazione e piano di controllo, registro di manutenzione e risultati dei campionamenti.",["Ho indicato il responsabile","Ho indicato i documenti"])],
 "Nel laboratorio imposti il piano di controllo della Legionella per docce e torre evaporativa: punti critici, misure, campionamenti e responsabilità. Confronta ogni risposta con la soluzione di riferimento.","Linee guida per la prevenzione e il controllo della legionellosi, 7 maggio 2015 · Titolo X D.lgs. 81/2008")])
EA(K,'ZR74','La UNI EN ISO 9612:2025',[LB("Laboratorio · La strategia di misura del rumore","Scegli la strategia di misura per tre gruppi omogenei di esposizione in una falegnameria.",[
  ["Gruppo 1","sezionatori: compiti ben definiti e ripetitivi (taglio, carico, pausa)"],["Gruppo 2","manutentori: attività variabili e imprevedibili durante la giornata"],["Gruppo 3","addetti al montaggio: mansione stabile con piccole variazioni"]],[
  ("Quale strategia scegli per ciascun gruppo e perché?",7,"Sezionatori: strategia basata sui compiti, perché i compiti sono definibili con durate note. Manutentori: strategia a giornata intera, per l’imprevedibilità delle attività. Montaggio: strategia basata sulla mansione, con campionamenti casuali sulla giornata.",["Ho scelto le tre strategie","Ho motivato le scelte"]),
  ("Come imposti le misure per i sezionatori?",7,"Analisi del lavoro con durate dei compiti; per ciascun compito un numero adeguato di misure rappresentative, con durata sufficiente a coprire le variazioni; registrazione delle condizioni operative e delle macchine.",["Ho previsto l’analisi del lavoro","Ho previsto più misure per compito"]),
  ("Perché l’incertezza è importante e come la usi?",6,"Il risultato si esprime con l’incertezza estesa U, stimata con il metodo della norma aggiornata: il confronto con i valori di azione e limite tiene conto di U, e una U elevata indica che servono più misure o una strategia diversa.",["Ho spiegato il ruolo dell’incertezza","Ho collegato U alle decisioni"])],
 "Nel laboratorio scegli la strategia di misura del rumore per tre gruppi di una falegnameria, imposti le misure e usi l’incertezza estesa. Confronta ogni risposta con la soluzione di riferimento.","UNI EN ISO 9612:2025 · art. 190 D.lgs. 81/2008")])
EA(K,'ZR75','Campi elettromagnetici e radiazioni ottiche artificiali',[LB("Laboratorio · Radiazioni ottiche e campi elettromagnetici in carpenteria","Valuti radiazioni ottiche e campi elettromagnetici in una carpenteria con saldatura e un forno a induzione.",[
  ["Sorgenti","saldatura ad arco MIG e TIG; taglio plasma; forno a induzione per riscaldamento di pezzi"],["Lavoratori","6 saldatori; 2 addetti al forno; un lavoratore portatore di pacemaker in magazzino"],["Presidi","maschere di saldatura; tende parziali"]],[
  ("Quali rischi da radiazioni ottiche individui?",6,"Radiazione ultravioletta, visibile e infrarossa dell’arco, con danni a occhi e pelle per i saldatori e per chi lavora vicino; la saldatura è tra le sorgenti che possono superare i valori limite.",["Ho indicato UV, visibile e infrarosso","Ho considerato i lavoratori vicini"]),
  ("Quali misure proponi per le radiazioni ottiche?",6,"Schermi e tende di separazione complete; maschere con filtri del grado adeguato al processo e alla corrente; indumenti che coprono la pelle; delimitazione delle aree e informazione agli altri lavoratori.",["Ho previsto schermature","Ho previsto DPI adeguati"]),
  ("Come gestisci il forno a induzione e il lavoratore con pacemaker?",7,"Valutazione dei campi del forno, anche con dati del fabbricante o misure; delimitazione delle zone in cui i campi superano i livelli per le persone con dispositivi impiantati; il lavoratore con pacemaker è un lavoratore particolarmente sensibile: accesso vietato a quelle zone, in accordo con il medico competente.",["Ho previsto la valutazione dei campi","Ho gestito il lavoratore sensibile"])],
 "Nel laboratorio valuti radiazioni ottiche e campi elettromagnetici in una carpenteria con saldatura e forno a induzione, inclusa la tutela di un lavoratore con pacemaker. Confronta ogni risposta con la soluzione di riferimento.","Titolo VIII, Capi IV e V, D.lgs. 81/2008")])
EA(K,'ZR76','Microclima: comfort e stress termico',[SC("L’ufficio troppo caldo","In un ufficio open space d’estate la temperatura arriva a 30 °C e le lamentele crescono. Il condizionatore è sottodimensionato.",[
 ("Che tipo di ambiente è e quale metodo usi?",[["Ambiente moderato: valutazione del comfort con PMV e PPD",True,"Corretto: UNI EN ISO 7730."],["Ambiente severo caldo con WBGT",False,"L’ufficio non è un ambiente severo."],["Non serve alcuna valutazione",False,"Le lamentele indicano discomfort."]]),
 ("Quali misure immediate proponi?",[["Schermature solari, ventilazione, regolazione degli orari e accesso all’acqua",True,"Corretto."],["Chiudere le finestre e basta",False,"Non risolve."],["Ridurre l’illuminazione al buio",False,"Non è una misura microclimatica adeguata."]]),
 ("E a medio termine?",[["Adeguamento dell’impianto di climatizzazione con progetto e manutenzione",True,"Corretto."],["Un ventilatore per persona",False,"Soluzione parziale."],["Nulla",False,"Il problema si ripresenta ogni estate."]])],
 "Negli ambienti moderati si valuta il comfort con PMV e PPD; schermature, ventilazione e organizzazione aiutano subito, l’impianto adeguato risolve.","Un ufficio troppo caldo d’estate. Valuta e intervieni.","Allegato IV D.lgs. 81/2008 · UNI EN ISO 7730")])
EA(K,'ZR77','Radiazioni ionizzanti e radon',[SC("Il controllo radiografico in officina","Un’impresa di carpenteria esegue controlli non distruttivi delle saldature con un apparecchio radiografico.",[
 ("Quale figura professionale serve?",[["L’esperto di radioprotezione, incaricato dal datore di lavoro",True,"Corretto: D.lgs. 101/2020."],["Il solo RSPP",False,"Serve una figura abilitata."],["Il medico di famiglia",False,"Non è pertinente."]]),
 ("Come si classificano i lavoratori e le aree?",[["Secondo la valutazione dell’esperto: lavoratori esposti di categoria A o B e zone controllate o sorvegliate",True,"Corretto."],["Tutti uguali",False,"La classificazione dipende dalle dosi."],["Non si classificano",False,"La classificazione è prevista."]]),
 ("Chi sorveglia la salute dei lavoratori esposti?",[["Il medico autorizzato per i lavoratori di categoria A; per la categoria B, il medico autorizzato o il medico competente, secondo la disciplina",True,"Corretto."],["Nessuno",False,"La sorveglianza è prevista."],["Solo l’esperto di radioprotezione",False,"Non è un medico."]])],
 "Le radiazioni ionizzanti hanno una disciplina propria: esperto di radioprotezione, classificazione di lavoratori e aree, sorveglianza medica dedicata.","Controlli radiografici in officina. Organizza la radioprotezione.","D.lgs. 101/2020")])
EA(K,'ZR78','Esercitazione 2 · Diisocianati',[AP("Agenti chimici, fisici e biologici nella tua realtà","Verifica lo stato delle valutazioni degli agenti.",["Valutazione chimica aggiornata con le SDS","Misure secondo UNI EN 689 dove necessarie","Valutazione del rumore secondo UNI EN ISO 9612:2025","Valutazione delle vibrazioni","Valutazione di ROA e campi elettromagnetici","Misure del radon nei locali interrati","Piano di controllo della Legionella"],"La valutazione da aggiornare per prima e perché","Es.: rumore, per l’arrivo di una nuova linea",
  "Verifica lo stato delle valutazioni di agenti chimici, fisici e biologici e indica quella da aggiornare per prima.",3)])
